// Push gate: decides whether a push may be sent to a user right now.
// It never sends anything. History is kept in memory only.

const KEEP_MS = 3 * 24 * 60 * 60 * 1000; // enough to cover any zone change within the current local day

const formatters = new Map();

function formatterFor(timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    // Throws RangeError for an unknown zone.
    f = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f;
}

// Returns { day: "YYYY-MM-DD", minute: minutes since local midnight } in the zone.
function localParts(date, timeZone) {
  const p = {};
  for (const { type, value } of formatterFor(timeZone).formatToParts(date)) p[type] = value;
  return { day: `${p.year}-${p.month}-${p.day}`, minute: Number(p.hour) * 60 + Number(p.minute) };
}

function parseClock(s) {
  const m = typeof s === 'string' ? /^([01]\d|2[0-3]):([0-5]\d)$/.exec(s) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

const deny = (reason) => ({ allowed: false, reason });

export function createPushGate() {
  const sent = new Map(); // user id -> array of send times (ms since epoch)

  function attempt(user, now) {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid_time');
    if (!user || typeof user.id !== 'string' || user.id === '') return deny('invalid_user');

    // Unknown or invalid settings are held, never guessed.
    if (typeof user.timeZone !== 'string') return deny('invalid_time_zone');
    let local;
    try {
      local = localParts(now, user.timeZone);
    } catch {
      return deny('invalid_time_zone');
    }
    const start = parseClock(user.quietStart);
    const end = parseClock(user.quietEnd);
    if (start === null || end === null) return deny('invalid_quiet_hours');
    const cap = user.dailyCap;
    if (!Number.isInteger(cap) || cap < 0) return deny('invalid_daily_cap');

    // Quiet window includes its start minute, excludes its end minute.
    // start > end wraps past midnight. start === end is an empty window.
    const quiet =
      start < end
        ? local.minute >= start && local.minute < end
        : start > end && (local.minute >= start || local.minute < end);
    if (quiet) return deny('quiet_hours');

    // "Per day" is the user's own local calendar day.
    const nowMs = now.getTime();
    const history = (sent.get(user.id) ?? []).filter((t) => nowMs - t < KEEP_MS);
    let today = 0;
    for (const t of history) {
      if (localParts(new Date(t), user.timeZone).day === local.day) today++;
    }
    if (today >= cap) {
      sent.set(user.id, history);
      return deny('daily_cap_reached');
    }

    history.push(nowMs);
    sent.set(user.id, history);
    return { allowed: true, reason: null };
  }

  return { attempt };
}

import assert from 'node:assert/strict';
import { createPushGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/ours-g2-2/bot.mjs';

const u = { id: 'u_8841', timeZone: 'Asia/Tokyo', quietStart: '22:00', quietEnd: '07:00', dailyCap: 3 };
const at = (iso) => new Date(iso);
// Tokyo = UTC+9. 12:00 Tokyo = 03:00Z
let g = createPushGate();
assert.deepEqual(g.attempt(u, at('2026-10-22T03:00:00Z')), { allowed: true, reason: null });
// quiet: 22:00 Tokyo = 13:00Z (start included), 06:59 Tokyo = 21:59Z, 07:00 Tokyo = 22:00Z allowed
g = createPushGate();
assert.equal(g.attempt(u, at('2026-10-22T12:59:00Z')).allowed, true);
g = createPushGate();
assert.equal(g.attempt(u, at('2026-10-22T13:00:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(u, at('2026-10-22T21:59:00Z')).reason, 'quiet_hours');
assert.equal(g.attempt(u, at('2026-10-22T22:00:00Z')).allowed, true);
// cap: refused don't count; local day rolls at local midnight (15:00Z)
g = createPushGate();
for (const h of ['00', '01', '02']) assert.equal(g.attempt(u, at(`2026-10-22T${h}:00:00Z`)).allowed, true);
assert.equal(g.attempt(u, at('2026-10-22T03:00:00Z')).reason, 'daily_cap_reached');
assert.equal(g.attempt(u, at('2026-10-22T14:59:00Z')).reason, 'quiet_hours'.length ? 'daily_cap_reached' : '');
// 00:00 Tokyo next day is quiet; 07:00 Tokyo (22:00Z) new day allowed
assert.equal(g.attempt(u, at('2026-10-22T22:00:00Z')).allowed, true);
// UTC day would differ: 2026-10-22T14:00Z is still Tokyo Oct 22 -> capped; same UTC day proves local day used
// independent gates, per-user
const g2 = createPushGate();
assert.equal(g2.attempt(u, at('2026-10-22T00:00:00Z')).allowed, true);
assert.equal(g2.attempt({ ...u, id: 'x', dailyCap: 0 }, at('2026-10-22T00:00:00Z')).reason, 'daily_cap_reached');
// non-wrapping window, other zone w/ DST
const ny = { id: 'n', timeZone: 'America/New_York', quietStart: '13:00', quietEnd: '14:00', dailyCap: 5 };
const g3 = createPushGate();
assert.equal(g3.attempt(ny, at('2026-11-01T17:30:00Z')).reason, 'quiet_hours'); // 12:30 EST after fallback? 17:30Z = 12:30 EST
assert.equal(g3.attempt(ny, at('2026-11-01T18:00:00Z')).reason, 'quiet_hours'); // 13:00 EST
assert.equal(g3.attempt(ny, at('2026-11-01T19:00:00Z')).allowed, true); // 14:00 EST
// invalid input held
assert.equal(g3.attempt({ ...ny, timeZone: 'Nope/Zone' }, at('2026-11-01T19:00:00Z')).reason, 'invalid_time_zone');
assert.equal(g3.attempt({ ...ny, quietStart: '25:00' }, at('2026-11-01T19:00:00Z')).reason, 'invalid_quiet_hours');
assert.equal(g3.attempt(ny, new Date(NaN)).reason, 'invalid_time');
